const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let p = 0;

const N = Number(input[p++]);
const X1 = BigInt(input[p++]);
const X2 = BigInt(input[p++]);

const lines = [];
for (let i = 0; i < N; i++) {
  const A = BigInt(input[p++]);
  const B = BigInt(input[p++]);
  lines.push({
    left: A * X1 + B,
    right: A * X2 + B
  });
}

function countEqualPairs(sorted, key) {
  let result = 0;
  for (let i = 0; i < sorted.length;) {
    let j = i + 1;
    while (j < sorted.length && sorted[j][key] === sorted[i][key]) j++;
    const size = j - i;
    result += size * (size - 1) / 2;
    i = j;
  }
  return result;
}

if (X1 === X2) {
  lines.sort((a, b) => a.left < b.left ? -1 : a.left > b.left ? 1 : 0);
  console.log(countEqualPairs(lines, 'left'));
} else {
  const byRight = lines.slice().sort((a, b) =>
    a.right < b.right ? -1 : a.right > b.right ? 1 : 0
  );

  let rank = 0;
  let previous = null;
  let rightTies = 0;

  for (let i = 0; i < byRight.length; i++) {
    if (i === 0 || byRight[i].right !== previous) {
      rank++;
      previous = byRight[i].right;
    } else {
      rightTies += 0;
    }
    byRight[i].rank = rank;
  }

  rightTies = countEqualPairs(byRight, 'right');

  lines.sort((a, b) => a.left < b.left ? -1 : a.left > b.left ? 1 : 0);

  const bit = new Int32Array(rank + 1);
  let inserted = 0;
  let crossings = 0;
  let leftTies = 0;

  function query(index) {
    let sum = 0;
    while (index > 0) {
      sum += bit[index];
      index -= index & -index;
    }
    return sum;
  }

  function update(index) {
    while (index <= rank) {
      bit[index]++;
      index += index & -index;
    }
  }

  for (let i = 0; i < N;) {
    let j = i + 1;
    while (j < N && lines[j].left === lines[i].left) j++;

    const size = j - i;
    leftTies += size * (size - 1) / 2;

    for (let k = i; k < j; k++) {
      crossings += inserted - query(lines[k].rank);
    }
    for (let k = i; k < j; k++) {
      update(lines[k].rank);
      inserted++;
    }
    i = j;
  }

  console.log(crossings + leftTies + rightTies);
}
